// =====================================================================
// ZENTRALE KONFIGURATION – hier pflegen
// =====================================================================
const CONFIG = {
  // --- Zeitfenster (Overlap-Puffer, Idempotenz faengt Doppelverarbeitung ab) ---
  fensterMinuten: 90,
  zeitzone: 'Europe/Berlin',
  // --- Abgrenzung der Altbestellungen ---------------------------------
  // Verifiziert 2026-08-10: kShop 3 = migrierter WooCommerce-Shop
  // (913.816 Bestellungen mit rein numerischer cBestellNr, davon 22.692 offen).
  kShopAlt: 3,
  // Zusaetzlich: nur rein numerische Bestellnummern (Woo-Nummernkreis).
  // Neuere JTL-Nummern in Shop 3 haben das Format 'A-2026-08-748421'.
  nurZiffernBestellnummer: true,
  // Obsolet durch den kShop-Filter – BB-/LEAF-/CINNA-/B2B- liegen in Shop 33/23/24/26.
  // Bleibt nur als Dokumentation stehen.
  praefixBlacklist: ['BB-', 'LEAF-', 'CINNA-', 'B2B-'],
  // Verifiziert 2026-08-10: nType 1 = Artikelposition.
  // Ausgeschlossen: 0/2/3/4/9 (kein Artikelbezug), 15 (Versandartikel), 16 (Storno).
  nTypeArtikel: [1],
  // --- Nummernkreis-Mapping -------------------------------------------
  // Verifiziert 2026-08-10: cBestellNr entspricht Shopify order.name (ohne '#').
  bestellnummerFeld: 'cBestellNr',   // Alternative: 'cInetBestellNr' (bei Shop 3 identisch)
  shopifyNamePrefix: '',
  // --- Shopify ---------------------------------------------------------
  shop: 'vdzvc0-nd',
  apiVersion: '2024-10',
  notifyCustomer: false,   // fachliche Entscheidung (Spec §7.3) – Altbestellungen!
  trackingSenden: false,   // Daten liegen jetzt vor (cIdentCodes/cLogistiker aus der SQL),
                           // nur sinnvoll, wenn benachrichtigt wird
  auditTagSetzen: true,
  // --- Mollie ----------------------------------------------------------
  mollieAktiv: true,
  mollieNurAuthorized: true,  // true = nur 'authorized' (Klarna) melden,
                              // bereits gecapturte Zahlungen werden uebersprungen
  // --- Betrieb ---------------------------------------------------------
  dryRun: true,            // true = KEINE Schreib-Calls an Shopify/Mollie
  reportEmpfaenger: 'PLATZHALTER@buecherbuechse.de'
};
const staticData = $getWorkflowStaticData('global');
staticData.config = CONFIG;
return [{ json: { config: CONFIG } }];

