/* ⚠️⚠️ PLATZHALTER – Status-Tabelle lesen (Idempotenz-Gate).
   Node ist DEAKTIVIERT: solange er inaktiv ist, findet der naechste
   Code-Node keine Statuszeilen und behandelt alles als 'pending'.

SELECT k_bestellung, bestellnummer, shopify_status, mollie_status,
       shopify_order_id, mollie_order_id
FROM   [n8n_status].[dbo].[fulfillment_status]
WHERE  k_bestellung IN ( {{ $items().map(i => i.json.kBestellung).join(',') }} );
*/
SELECT 1;

parameters.jsCode:
// Idempotenz-Gate: Kandidaten mit dem Status aus der Status-Tabelle verheiraten.
// Solange die Status-Nodes deaktiviert sind, ist alles 'pending'.
const config     = $('Config').first().json.config;
const kandidaten = $('JTL: Kandidaten + Vollstaendigkeit').all()
                     .map(i => i.json)
                     .filter(r => r && r.kBestellung !== undefined);

// ⚠️ PLATZHALTER: Feldnamen an die spaetere Status-Tabelle anpassen.
const statusRows = $input.all().map(i => i.json).filter(r => r && r.k_bestellung != null);
const statusMap  = new Map(statusRows.map(r => [Number(r.k_bestellung), r]));

const erledigt = (s) => s === 'done' || String(s || '').startsWith('skipped_');

return kandidaten.map(k => {
  const st = statusMap.get(Number(k.kBestellung)) || {};
  const bestellnummer = String(k[config.bestellnummerFeld] ?? '').trim();

  return {
    json: {
      kBestellung:       Number(k.kBestellung),
      bestellnummer,
      shopifyOrderName:  config.shopifyNamePrefix + bestellnummer,
      lieferscheine:     k.cLieferscheine ?? null,
      dVersendetMax:     k.dVersendetMax ?? null,
      kShop:             k.kShop ?? null,

      shopifyStatusVorher: st.shopify_status ?? 'pending',
      mollieStatusVorher:  st.mollie_status  ?? 'pending',
      shopifyOffen:        !erledigt(st.shopify_status),
      mollieOffen:         config.mollieAktiv && !erledigt(st.mollie_status),

      // ⚠️ PLATZHALTER: aus der Status-Tabelle bzw. dem Mapping
      mollieOrderIdVorher: st.mollie_order_id ?? null,

      dryRun: config.dryRun,
      runId:  $execution.id
    }
  };
});

// Auswertung der Order-Abfrage -> entscheidet, ob ein Fulfillment angelegt wird.
const config = $('Config').first().json.config;
const src    = $('Loop Over Items').item.json;
const resp   = $input.first().json;

const raus = (status, message, extra = {}) =>
  [{ json: { ...src, shopifyAktion: 'skip', shopifyStatus: status, shopifyMessage: message, ...extra } }];

if (resp?.error || resp?.errors) {
  return raus('error', 'Order-Abfrage fehlgeschlagen: ' + JSON.stringify(resp.error || resp.errors).slice(0, 500));
}

const edges   = resp?.data?.orders?.edges || [];
const treffer = edges.find(e => String(e.node.name).trim() === String(src.shopifyOrderName).trim());

if (!treffer) return raus('skipped_not_found', 'Keine Shopify-Bestellung mit name=' + src.shopifyOrderName);

const order = treffer.node;
if (order.cancelledAt)                        return raus('skipped_cancelled', 'Bestellung storniert', { shopifyOrderId: order.id });
if (order.displayFulfillmentStatus === 'FULFILLED') return raus('skipped_already_fulfilled', 'Bereits fulfilled', { shopifyOrderId: order.id });

const fos = (order.fulfillmentOrders?.edges || [])
  .map(e => e.node)
  .filter(n => ['OPEN', 'IN_PROGRESS'].includes(n.status));

if (!fos.length) return raus('skipped_no_fulfillment_order',
  'Keine offene Fulfillment Order (Status: ' + order.displayFulfillmentStatus + ')', { shopifyOrderId: order.id });

return [{
  json: {
    ...src,
    shopifyAktion:        config.dryRun ? 'dry_run' : 'create',
    shopifyStatus:        config.dryRun ? 'pending' : 'pending',
    shopifyOrderId:       order.id,
    shopifyOrderClosed:   order.closed,
    fulfillmentOrderIds:  fos.map(f => f.id),
    // ⚠️ PLATZHALTER: Trackingnummer (tVersand.cIdentCode) wird derzeit nicht mitgelesen
    trackingNummer:       null,
    trackingCarrier:      null
  }
}];

// Body fuer fulfillmentCreate. Ohne lineItems-Angabe = alle Positionen der FO.
// ⚠️ PRUEFEN: in API 2024-10 heisst die Mutation `fulfillmentCreate`
//    (frueher `fulfillmentCreateV2`). Bei Fehler 'Field does not exist' umbenennen.
const config = $('Config').first().json.config;
const item   = $input.first().json;

const fulfillment = {
  notifyCustomer: config.notifyCustomer,
  lineItemsByFulfillmentOrder: item.fulfillmentOrderIds.map(id => ({ fulfillmentOrderId: id }))
};

if (config.trackingSenden && item.trackingNummer) {
  fulfillment.trackingInfo = {
    number:  item.trackingNummer,
    company: item.trackingCarrier || 'PLATZHALTER-Carrier'
  };
}

const body = {
  query: `mutation fulfillmentCreate($fulfillment: FulfillmentInput!) {
    fulfillmentCreate(fulfillment: $fulfillment) {
      fulfillment { id status createdAt }
      userErrors { field message }
    }
  }`,
  variables: { fulfillment }
};

return [{ json: { ...item, gqlBody: JSON.stringify(body) } }];

// userErrors auswerten (Muster aus Flow B), aber NICHT throwen:
// Fehler landen im Status und werden im naechsten Run erneut versucht.
const src  = $('Query bauen (fulfillmentCreate)').item.json;
const resp = $input.first().json;

if (resp?.error || resp?.errors) {
  return [{ json: { ...src, shopifyStatus: 'error',
    shopifyMessage: 'HTTP/GraphQL-Fehler: ' + JSON.stringify(resp.error || resp.errors).slice(0, 500) } }];
}

const res  = resp?.data?.fulfillmentCreate;
const errs = res?.userErrors || [];

if (errs.length) {
  return [{ json: { ...src, shopifyStatus: 'error', shopifyMessage: 'userErrors: ' + JSON.stringify(errs) } }];
}

return [{ json: { ...src, shopifyStatus: 'done', shopifyMessage: null,
                  shopifyFulfillmentId: res?.fulfillment?.id || null } }];

