/* ⚠️⚠️ PLATZHALTER – Status A schreiben. Node ist DEAKTIVIERT.

UPDATE [n8n_status].[dbo].[fulfillment_status]
SET    shopify_order_id = '{{ $json.shopifyOrderId }}',
       shopify_status   = '{{ $json.shopifyStatus }}',
       shopify_at       = SYSDATETIME(),
       shopify_message  = '{{ $json.shopifyMessage }}'
WHERE  k_bestellung = {{ $json.kBestellung }};
*/
SELECT 1;

parameters.jsCode:
// =====================================================================
// ⚠️⚠️⚠️ PLATZHALTER – HAUPTBLOCKER (Spec §8.2)
// Mollie kennt keine Suche nach orderNumber. Hier muss das Mapping
//   Bestellnummer  ->  Mollie-Order-ID (ord_...)
// aufgeloest werden. Optionen in Prioritaetsreihenfolge:
//   1) Feld aus JTL (tZahlung / cTransaktionsID) – dann direkt in der SQL mitlesen
//   2) einmaliger Export der WooCommerce-Order-Meta (_mollie_order_id) in eine Mapping-Tabelle
//   3) Vollexport ueber GET /v2/orders paginieren (Cursor-Muster aus Flow B)
// =====================================================================
const src = $input.first().json;

// PLATZHALTER: Auflaesung hier einsetzen (DB-Lookup / Mapping-Objekt)
const mollieOrderId = src.mollieOrderIdVorher || null;

if (!mollieOrderId) {
  return [{ json: { ...src, mollieOrderId: null, mollieAktion: 'skip',
    mollieStatus: 'skipped_no_mollie',
    mollieMessage: 'Kein Mapping Bestellnummer -> Mollie-Order-ID vorhanden (PLATZHALTER)' } }];
}

return [{ json: { ...src, mollieOrderId, mollieAktion: 'pruefen' } }];

// Mollie-Status auswerten und entscheiden, ob ein Shipment gemeldet wird.
const config = $('Config').first().json.config;
const src    = $('⚠️ PLATZHALTER Mollie-Order-ID aufloesen').item.json;
const resp   = $input.first().json;

const raus = (status, message, extra = {}) =>
  [{ json: { ...src, mollieAktion: 'skip', mollieStatus: status, mollieMessage: message, ...extra } }];

if (resp?.error || resp?.status >= 400) {
  return raus('error', 'Mollie-Abfrage fehlgeschlagen: ' + JSON.stringify(resp.error || resp).slice(0, 500));
}

const status = String(resp?.status || '');
const method = String(resp?.method || '');

if (['completed', 'shipping'].includes(status)) return raus('skipped_already_shipped', 'Mollie-Status: ' + status);
if (['canceled', 'expired'].includes(status))   return raus('skipped_' + status, 'Mollie-Status: ' + status);

// Nur 'authorized' muss zwingend gemeldet werden (Klarna-Capture).
if (config.mollieNurAuthorized && status !== 'authorized') {
  return raus('skipped_no_capture_needed', 'Zahlung bereits gecaptured (' + status + ' / ' + method + ')');
}

if (config.dryRun) return raus('pending', 'Dry-Run: Shipment nicht gemeldet');

return [{ json: { ...src, mollieAktion: 'shipment', mollieStatus: 'pending',
                  mollieOrderStatus: status, mollieMethod: method } }];

const src  = $('Mollie-Status auswerten').item.json;
const resp = $input.first().json;

if (resp?.error || (resp?.status && Number(resp.status) >= 400) || resp?.detail) {
  return [{ json: { ...src, mollieStatus: 'error',
    mollieMessage: 'Shipment fehlgeschlagen: ' + JSON.stringify(resp.error || resp).slice(0, 500) } }];
}

return [{ json: { ...src, mollieStatus: 'done', mollieMessage: null,
                  mollieShipmentId: resp?.id || null } }];

