/* ⚠️⚠️ PLATZHALTER – Status B schreiben. Node ist DEAKTIVIERT.

UPDATE [n8n_status].[dbo].[fulfillment_status]
SET    mollie_order_id = '{{ $json.mollieOrderId }}',
       mollie_status   = '{{ $json.mollieStatus }}',
       mollie_at       = SYSDATETIME(),
       mollie_message  = '{{ $json.mollieMessage }}'
WHERE  k_bestellung = {{ $json.kBestellung }};
*/
SELECT 1;

parameters.jsCode:
// Sammelt alle Ergebnisse der Ausfuehrung fuer die Report-Mail.
const config = $('Config').first().json.config;

const zeilen = $input.all().map(i => i.json).filter(r => r && r.kBestellung);
const zaehl = (feld) => zeilen.reduce((acc, r) => {
  const k = r[feld] || 'unbekannt';
  acc[k] = (acc[k] || 0) + 1;
  return acc;
}, {});

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const tabelle = zeilen.map(r => `<tr>
  <td>${esc(r.bestellnummer)}</td>
  <td>${esc(r.lieferscheine)}</td>
  <td>${esc(r.shopifyStatus || '-')}</td>
  <td>${esc(r.mollieStatus || '-')}</td>
  <td>${esc(r.shopifyMessage || r.mollieMessage || '')}</td>
</tr>`).join('');

const mailText = `
<p><b>JTL &rarr; Shopify + Mollie Fulfillment</b> ${config.dryRun ? '<b>(DRY RUN)</b>' : ''}</p>
<p>Verarbeitete Bestellungen: ${zeilen.length}<br>
Shopify: ${esc(JSON.stringify(zaehl('shopifyStatus')))}<br>
Mollie: ${esc(JSON.stringify(zaehl('mollieStatus')))}</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:Arial;font-size:13px">
<thead><tr><th>Bestellnr</th><th>Lieferscheine</th><th>Shopify</th><th>Mollie</th><th>Meldung</th></tr></thead>
<tbody>${tabelle}</tbody></table>
`;

return [{ json: {
  titel: 'JTL Fulfillment ' + $now.setZone(config.zeitzone).toFormat('yyyy-MM-dd HH:mm'),
  sendto: config.reportEmpfaenger,   // ⚠️ PLATZHALTER Empfaengerkreis
  anzahl: zeilen.length,
  mailText
} }];
